package io.atlas.modules.pokedex.repository;
import io.atlas.modules.database.DatabaseConfig;
import io.atlas.modules.pokedex.model.DexRewardPlan;
import java.sql.*;import java.util.*;
public final class DexRewardRepository {
 public record Reward(UUID id,UUID player,int milestone,int part,String kind,String value,int amount,String state,String data,String route){public Reward(UUID id,UUID player,int milestone,int part,String kind,String value,int amount,String state,String data){this(id,player,milestone,part,kind,value,amount,state,data,"main");}}
 private Connection connect()throws SQLException{var p=new Properties();p.setProperty("user",DatabaseConfig.USER);p.setProperty("password",DatabaseConfig.PASSWORD);p.setProperty("connectTimeout","3");p.setProperty("socketTimeout","10");return DriverManager.getConnection(DatabaseConfig.jdbcUrl(),p);}
 public void unlock(UUID player,int milestone){unlock(player,"main",milestone);}
 public void unlock(UUID player,String route,int milestone){if(!route.equals("main")&&!io.atlas.modules.pokedex.model.TypeRoutePlan.ROUTES.contains(route))throw new IllegalArgumentException();try(var c=connect()){
  c.setAutoCommit(false);
  try{for(int m:route.equals("main")?java.util.stream.IntStream.rangeClosed(1,10).map(x->x*10).boxed().toList():io.atlas.modules.pokedex.model.TypeRoutePlan.MARKS){if(m>milestone)continue;var parts=route.equals("main")?DexRewardPlan.parts(m):io.atlas.modules.pokedex.model.TypeRoutePlan.parts(m,route);for(int i=0;i<parts.size();i++){var part=parts.get(i);try(var p=c.prepareStatement("INSERT INTO pokedex_rewards(id,uuid,milestone,part,kind,value,amount,state,route) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(uuid,route,milestone,part) DO NOTHING")){p.setObject(1,UUID.randomUUID());p.setObject(2,player);p.setInt(3,m);p.setInt(4,i);p.setString(5,part.kind());p.setString(6,part.value());p.setInt(7,part.amount());p.setString(8,part.kind().equals("MINT")||part.kind().equals("LEGENDARY_CHOICE")?"CHOICE":"AVAILABLE");p.setString(9,route);p.executeUpdate();}}}c.commit();}catch(Exception e){c.rollback();throw e;}
 }catch(SQLException e){throw new IllegalStateException(e);}}
 private Reward row(ResultSet r)throws SQLException{return new Reward(r.getObject("id",UUID.class),r.getObject("uuid",UUID.class),r.getInt("milestone"),r.getInt("part"),r.getString("kind"),r.getString("value"),r.getInt("amount"),r.getString("state"),r.getString("payload"),r.getString("route"));}
 public List<Reward> list(UUID player){return list(player,"main");}
 public List<Reward> list(UUID player,String route){var out=new ArrayList<Reward>();try(var c=connect();var p=c.prepareStatement("SELECT * FROM pokedex_rewards WHERE uuid=? AND route=? ORDER BY milestone,part")){p.setObject(1,player);p.setString(2,route);try(var r=p.executeQuery()){while(r.next())out.add(row(r));}return out;}catch(SQLException e){throw new IllegalStateException(e);}}
 public List<Reward> pending(){var out=new ArrayList<Reward>();try(var c=connect();var p=c.prepareStatement("SELECT * FROM pokedex_rewards WHERE state IN ('PENDING','READY','DELIVERING') AND EXISTS(SELECT 1 FROM players p WHERE p.uuid=pokedex_rewards.uuid AND p.is_online) ORDER BY created_at,milestone,part LIMIT 100");var r=p.executeQuery()){while(r.next())out.add(row(r));return out;}catch(SQLException e){throw new IllegalStateException(e);}}
 public void claim(UUID player,int milestone){claim(player,"main",milestone);}
 public void claim(UUID player,String route,int milestone){try(var c=connect();var p=c.prepareStatement("UPDATE pokedex_rewards SET state='PENDING' WHERE uuid=? AND milestone=? AND route=? AND state='AVAILABLE'")){p.setObject(1,player);p.setInt(2,milestone);p.setString(3,route);p.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}
 public boolean choice(UUID player,int milestone,String kind,String value){return choice(player,"main",milestone,kind,value);}
 public boolean choice(UUID player,String route,int milestone,String kind,String value){try(var c=connect();var p=c.prepareStatement("UPDATE pokedex_rewards SET value=?,state='PENDING' WHERE id=(SELECT id FROM pokedex_rewards WHERE uuid=? AND milestone=? AND kind=? AND route=? AND state='CHOICE' ORDER BY part LIMIT 1 FOR UPDATE SKIP LOCKED) AND state='CHOICE'")){p.setString(1,value);p.setObject(2,player);p.setInt(3,milestone);p.setString(4,kind);p.setString(5,route);return p.executeUpdate()==1;}catch(SQLException e){throw new IllegalStateException(e);}}
 public boolean prepare(UUID id,String payload){try(var c=connect();var p=c.prepareStatement("UPDATE pokedex_rewards SET payload=?::jsonb,state='READY' WHERE id=? AND state='PENDING'")){p.setString(1,payload);p.setObject(2,id);return p.executeUpdate()==1;}catch(SQLException e){throw new IllegalStateException(e);}}
 public boolean transition(UUID id,String from,String to){if(!Set.of("READY","DELIVERING","DELIVERED","REVIEW").contains(to))throw new IllegalArgumentException();try(var c=connect();var p=c.prepareStatement("UPDATE pokedex_rewards SET state=?,delivered_at=CASE WHEN ?='DELIVERED' THEN now() ELSE delivered_at END WHERE id=? AND state=?")){p.setString(1,to);p.setString(2,to);p.setObject(3,id);p.setString(4,from);return p.executeUpdate()==1;}catch(SQLException e){throw new IllegalStateException(e);}}
}
